-- Fantasy Friends executable migration 20261116235900_idempotent_match_lineup_submission
-- Generated by scripts/promote-migrations.mjs from supabase/design/migrations/024_idempotent_match_lineup_submission.sql
-- Do not edit by hand: the guard re-derives this file and fails on drift.

-- Make the existing lineup submission RPC retry-safe for clients whose response
-- is lost after the database committed. Match locking serializes concurrent calls;
-- the original immutable submission and any approval are returned on replay.
--
-- This does not skip submit-time lineup validation: only the first call inserts,
-- and its existing match_submissions trigger still checks both teams, starter
-- counts, eligibility, and authorization before the state can advance.

begin;

create or replace function public.ff_match_submit_lineup(p_league uuid,p_revision uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare
  v_match_id uuid;
  v_submission_id uuid;
  v_approval_id uuid;
  v_decision text;
begin
  select r.match_id into v_match_id
    from public.match_revisions r
    where r.league_id=p_league and r.id=p_revision;
  if not found then raise exception 'revision not found' using errcode='42501'; end if;

  -- Lock in the established match -> revision/workflow order before replay
  -- lookup. This prevents simultaneous browser retries from racing the unique
  -- revision submission constraint or attempting a duplicate approval.
  perform 1 from public.real_matches m
    where m.league_id=p_league and m.id=v_match_id for update;
  if not found then raise exception 'match not found' using errcode='42501'; end if;
  perform ff_private.require_organizer(p_league,v_match_id);

  select s.id,a.id,a.decision
    into v_submission_id,v_approval_id,v_decision
    from public.match_submissions s
    left join public.match_approvals a
      on a.league_id=s.league_id and a.submission_id=s.id
    where s.league_id=p_league and s.match_id=v_match_id
      and s.revision_id=p_revision and s.kind='lineup';
  if found then
    return jsonb_build_object(
      'submission_id',v_submission_id,
      'approval_id',v_approval_id,
      'state',case v_decision when 'approved' then 'approved' when 'rejected' then 'rejected' else 'submitted' end
    );
  end if;

  -- Keep the existing submit helper and trigger-based validation as the only
  -- path that creates a submission.
  v_submission_id:=ff_private.submit_lineup(p_league,p_revision);
  if ff_private.is_leader(p_league) then
    insert into public.match_approvals(league_id,match_id,submission_id,revision_id,kind,decision,reviewed_by)
    values(p_league,v_match_id,v_submission_id,p_revision,'lineup','approved',ff_private.current_actor_id())
    returning id into v_approval_id;
    return jsonb_build_object('submission_id',v_submission_id,'approval_id',v_approval_id,'state','approved');
  end if;

  perform ff_private.notify_leader(p_league,'lineup_submitted',
    jsonb_build_object('submission_id',v_submission_id,'match_id',v_match_id,'league_id',p_league));
  return jsonb_build_object('submission_id',v_submission_id,'state','submitted');
end $$;

commit;
